from __future__ import annotations

"""Assignments that grant access to a group rather than to individual users.

An access package, a license SKU, or a directory role can be assigned to a
group. Everyone who is an effective member of that group inherits the grant.
This module records the raw assignments; turning them into per-user access is
done by the effective-access layer that reads the resolver.
"""

from dataclasses import dataclass, field


VALID_KINDS = ("access_package", "license", "role")


@dataclass(frozen=True)
class Assignment:
    resource_kind: str
    resource_id: str
    group_id: str

    def __post_init__(self) -> None:
        if self.resource_kind not in VALID_KINDS:
            raise ValueError(f"unknown resource_kind {self.resource_kind!r}")
        if not self.resource_id.strip():
            raise ValueError("resource_id is required")
        if not self.group_id.strip():
            raise ValueError("group_id is required")

    def resource(self) -> tuple[str, str]:
        return (self.resource_kind, self.resource_id)


@dataclass
class AssignmentBook:
    _assignments: list[Assignment] = field(default_factory=list)

    def assign(self, resource_kind: str, resource_id: str, group_id: str) -> Assignment:
        assignment = Assignment(resource_kind, resource_id, group_id)
        if assignment not in self._assignments:
            self._assignments.append(assignment)
        return assignment

    def assign_package(self, package_id: str, group_id: str) -> Assignment:
        return self.assign("access_package", package_id, group_id)

    def assign_license(self, sku_id: str, group_id: str) -> Assignment:
        return self.assign("license", sku_id, group_id)

    def assign_role(self, role_id: str, group_id: str) -> Assignment:
        return self.assign("role", role_id, group_id)

    def all(self) -> list[Assignment]:
        return list(self._assignments)

    def for_group(self, group_id: str) -> list[Assignment]:
        return [a for a in self._assignments if a.group_id == group_id]

    def for_resource(self, resource_kind: str, resource_id: str) -> list[Assignment]:
        return [
            a
            for a in self._assignments
            if a.resource_kind == resource_kind and a.resource_id == resource_id
        ]

    def groups_with_resource(self, resource_kind: str, resource_id: str) -> list[str]:
        return [a.group_id for a in self.for_resource(resource_kind, resource_id)]

    def resources_for_group(self, group_id: str) -> list[tuple[str, str]]:
        return [a.resource() for a in self.for_group(group_id)]

    def assigned_group_ids(self) -> list[str]:
        return list({a.group_id for a in self._assignments})

    def resource_ids(self, resource_kind: str) -> list[str]:
        return list({a.resource_id for a in self._assignments if a.resource_kind == resource_kind})

    def count(self) -> int:
        return len(self._assignments)

    def is_empty(self) -> bool:
        return not self._assignments

    def remove_for_group(self, group_id: str) -> None:
        self._assignments = [a for a in self._assignments if a.group_id != group_id]


def build_assignment_book(specs: list[tuple[str, str, str]] | None = None) -> AssignmentBook:
    """Build a book from (resource_kind, resource_id, group_id) tuples."""

    book = AssignmentBook()
    for kind, resource_id, group_id in specs or []:
        book.assign(kind, resource_id, group_id)
    return book

