from __future__ import annotations

"""Domain types for an Entra ID directory slice.

A directory holds two kinds of principals: users and groups. A group can list
both users and other groups as members, nested to any depth. Admins build these
trees by hand in the portal, so the same user can be reachable through several
branches, and occasionally two groups end up pointing at each other.

The objects here are deliberately small. Resolving who actually belongs to a
group (directly or through nesting) happens elsewhere; this module only models
the principals and the raw membership edges.
"""

from dataclasses import dataclass, field


@dataclass(frozen=True)
class User:
    object_id: str
    user_principal_name: str = ""
    account_enabled: bool = True

    def __post_init__(self) -> None:
        if not self.object_id.strip():
            raise ValueError("object_id is required")


@dataclass
class Group:
    object_id: str
    display_name: str = ""
    # Raw member references as they appear in the directory. Each entry is a
    # (kind, object_id) pair where kind is "user" or "group".
    member_refs: list[tuple[str, str]] = field(default_factory=list)

    def __post_init__(self) -> None:
        if not self.object_id.strip():
            raise ValueError("object_id is required")

    def add_member(self, kind: str, object_id: str) -> None:
        if kind not in ("user", "group"):
            raise ValueError(f"unknown member kind {kind!r}")
        if not object_id.strip():
            raise ValueError("member object_id is required")
        ref = (kind, object_id)
        if ref not in self.member_refs:
            self.member_refs.append(ref)

    def add_user(self, object_id: str) -> None:
        self.add_member("user", object_id)

    def add_group(self, object_id: str) -> None:
        self.add_member("group", object_id)

    def user_refs(self) -> list[str]:
        return [oid for kind, oid in self.member_refs if kind == "user"]

    def group_refs(self) -> list[str]:
        return [oid for kind, oid in self.member_refs if kind == "group"]

    def is_empty(self) -> bool:
        return not self.member_refs


@dataclass(frozen=True)
class MembershipEdge:
    parent_group_id: str
    member_kind: str
    member_id: str


def edges_of(group: Group) -> list[MembershipEdge]:
    """Flatten a group's direct member references into edge records."""

    return [
        MembershipEdge(parent_group_id=group.object_id, member_kind=kind, member_id=oid)
        for kind, oid in group.member_refs
    ]


def build_user(object_id: str, upn: str = "", enabled: bool = True) -> User:
    return User(object_id=object_id, user_principal_name=upn, account_enabled=enabled)


def build_group(object_id: str, display_name: str = "", members: list[tuple[str, str]] | None = None) -> Group:
    """Construct a group from optional (kind, object_id) member pairs."""

    group = Group(object_id=object_id, display_name=display_name)
    for kind, oid in members or []:
        group.add_member(kind, oid)
    return group


def split_refs(refs: list[tuple[str, str]]) -> tuple[list[str], list[str]]:
    """Partition member refs into (user_ids, group_ids)."""

    users = [oid for kind, oid in refs if kind == "user"]
    groups = [oid for kind, oid in refs if kind == "group"]
    return users, groups

