from __future__ import annotations

"""Turn group assignments into per-user effective access.

A resource assigned to a group reaches every effective member of that group,
including users buried under several layers of nested groups. This layer joins
the assignment book to the resolved membership so callers can ask "does this
user have this access package?" or "who can see this license?".
"""

from access_assignments import AssignmentBook
from group_directory import GroupDirectory
from membership_resolver import resolve_user_members


class EffectiveAccess:
    def __init__(self, directory: GroupDirectory, book: AssignmentBook) -> None:
        self._directory = directory
        self._book = book

    def users_with_resource(self, resource_kind: str, resource_id: str) -> set[str]:
        """Every user who inherits a resource through any assigned group."""

        reached: set[str] = set()
        for group_id in self._book.groups_with_resource(resource_kind, resource_id):
            reached |= resolve_user_members(self._directory, group_id)
        return reached

    def users_with_package(self, package_id: str) -> set[str]:
        return self.users_with_resource("access_package", package_id)

    def users_with_license(self, sku_id: str) -> set[str]:
        return self.users_with_resource("license", sku_id)

    def users_with_role(self, role_id: str) -> set[str]:
        return self.users_with_resource("role", role_id)

    def user_has_resource(self, user_id: str, resource_kind: str, resource_id: str) -> bool:
        return user_id in self.users_with_resource(resource_kind, resource_id)

    def resources_for_user(self, user_id: str) -> list[tuple[str, str]]:
        """All (kind, resource_id) pairs the user inherits from any group."""

        granted: set[tuple[str, str]] = set()
        for assignment in self._book.all():
            members = resolve_user_members(self._directory, assignment.group_id)
            if user_id in members:
                granted.add(assignment.resource())
        return sorted(granted)

    def user_has_any_access(self, user_id: str) -> bool:
        return bool(self.resources_for_user(user_id))

    def access_count_for_user(self, user_id: str) -> int:
        return len(self.resources_for_user(user_id))

    def resource_reach(self) -> dict[tuple[str, str], int]:
        """How many distinct users each assigned resource reaches."""

        return {resource: len(users) for resource, users in self.users_for_each_resource().items()}

    def users_for_each_resource(self) -> dict[tuple[str, str], set[str]]:
        out: dict[tuple[str, str], set[str]] = {}
        for assignment in self._book.all():
            resource = assignment.resource()
            members = resolve_user_members(self._directory, assignment.group_id)
            out[resource] = out.get(resource, set()) | members
        return out


def summarize_resource_access(
    directory: GroupDirectory,
    book: AssignmentBook,
    resource_kind: str,
    resource_id: str,
) -> dict[str, object]:
    """A small report for one resource: assigned groups and effective users."""

    access = EffectiveAccess(directory, book)
    groups = book.groups_with_resource(resource_kind, resource_id)
    users = access.users_with_resource(resource_kind, resource_id)
    return {
        "resource_kind": resource_kind,
        "resource_id": resource_id,
        "assigned_groups": sorted(groups),
        "effective_user_count": len(users),
        "effective_users": sorted(users),
    }

