    def link_group(self, parent_group_id: str, child_group_id: str) -> None:
        self.link_member(parent_group_id, "group", child_group_id)

    # --- lookups ------------------------------------------------------

    def get_user(self, object_id: str) -> User | None:
        return self._users.get(object_id)

    def get_group(self, object_id: str) -> Group | None:
        return self._groups.get(object_id)

    def require_group(self, object_id: str) -> Group:
        group = self._groups.get(object_id)
        if group is None:
            raise KeyError(f"unknown group {object_id}")
        return group

    def has_group(self, object_id: str) -> bool:
        return object_id in self._groups

    def has_user(self, object_id: str) -> bool:
        return object_id in self._users

    def is_group(self, object_id: str) -> bool:
        return object_id in self._groups

    def direct_member_refs(self, group_id: str) -> list[tuple[str, str]]:
        return list(self.require_group(group_id).member_refs)

    def direct_user_ids(self, group_id: str) -> list[str]:
        return self.require_group(group_id).user_refs()

    def direct_group_ids(self, group_id: str) -> list[str]:
        return self.require_group(group_id).group_refs()

    # --- bulk views ---------------------------------------------------

    def group_ids(self) -> list[str]:
        return list(self._groups)

    def user_ids(self) -> list[str]:
        return list(self._users)

    def group_count(self) -> int:
        return len(self._groups)

    def user_count(self) -> int:
        return len(self._users)

    def known_user(self, object_id: str) -> bool:
        return object_id in self._users


def build_directory(
    users: list[str] | None = None,
    groups: list[str] | None = None,
    links: list[tuple[str, str, str]] | None = None,
) -> GroupDirectory:
    """Assemble a directory from ids and (parent, kind, member) link tuples."""

    directory = GroupDirectory()
    for uid in users or []:
        directory.upsert_user(uid)
    for gid in groups or []:
        directory.upsert_group(gid)
    for parent, kind, member in links or []:
        directory.link_member(parent, kind, member)
    return directory

