from __future__ import annotations

"""Resolve the effective (transitive) user members of a group.

A group's effective users are everyone reachable by walking direct user members
plus the user members of every nested group, to any depth. The same user can sit
under several branches; the resolved set must list each user once. The directory
is hand-built by admins, so a nested group can point back at an ancestor and form
a loop. Resolution still has to come back with the right set of users.
"""

from group_directory import GroupDirectory


def resolve_user_members(directory: GroupDirectory, group_id: str) -> set[str]:
    """Return the object ids of every user reachable from group_id.

    Walks direct user members and recurses into every nested group member.
    """

    directory.require_group(group_id)
    members: set[str] = set()
    _collect(directory, group_id, members)
    return members


def _collect(directory: GroupDirectory, group_id: str, members: set[str]) -> None:
    group = directory.get_group(group_id)
    if group is None:
        return
    for kind, member_id in group.member_refs:
        if kind == "user":
            members.add(member_id)
        else:
            _collect(directory, member_id, members)


def resolve_user_member_list(directory: GroupDirectory, group_id: str) -> list[str]:
    """Sorted list form of resolve_user_members for stable output."""

    return sorted(resolve_user_members(directory, group_id))


def effective_member_count(directory: GroupDirectory, group_id: str) -> int:
    return len(resolve_user_members(directory, group_id))


def is_effective_member(directory: GroupDirectory, group_id: str, user_id: str) -> bool:
    return user_id in resolve_user_members(directory, group_id)


def reachable_groups(directory: GroupDirectory, group_id: str) -> set[str]:
    """All nested group ids reachable from group_id, including itself."""

    directory.require_group(group_id)
    seen: set[str] = set()
    _walk_groups(directory, group_id, seen)
    return seen


def _walk_groups(directory: GroupDirectory, group_id: str, seen: set[str]) -> None:
    if group_id in seen:
        return
    seen.add(group_id)
    group = directory.get_group(group_id)
    if group is None:
        return
    for child in group.group_refs():
        _walk_groups(directory, child, seen)


def resolve_many(directory: GroupDirectory, group_ids: list[str]) -> dict[str, set[str]]:
    """Resolve effective users for a batch of groups."""

    return {gid: resolve_user_members(directory, gid) for gid in group_ids}


def union_user_members(directory: GroupDirectory, group_ids: list[str]) -> set[str]:
    """Union of effective users across several groups (deduped)."""

    result: set[str] = set()
    for gid in group_ids:
        result |= resolve_user_members(directory, gid)
    return result


def has_cycle(directory: GroupDirectory, group_id: str) -> bool:
    """Whether the group-to-group nesting under group_id contains a loop."""

    directory.require_group(group_id)
    visiting: set[str] = set()
    done: set[str] = set()
    return _detect_cycle(directory, group_id, visiting, done)


def _detect_cycle(
    directory: GroupDirectory,
    group_id: str,
    visiting: set[str],
    done: set[str],
) -> bool:
    if group_id in visiting:
        return True
    if group_id in done:
        return False
    group = directory.get_group(group_id)
    if group is None:
        done.add(group_id)
        return False
    visiting.add(group_id)
    for child in group.group_refs():
        if _detect_cycle(directory, child, visiting, done):
            return True
    visiting.discard(group_id)
    done.add(group_id)
    return False


def nesting_depth(directory: GroupDirectory, group_id: str) -> int:
    """Longest nested-group chain length under group_id (cycle-safe)."""

    directory.require_group(group_id)
    return _depth(directory, group_id, set())


def _depth(directory: GroupDirectory, group_id: str, on_path: set[str]) -> int:
    group = directory.get_group(group_id)
    if group is None or group_id in on_path:
        return 0
    children = group.group_refs()
    if not children:
        return 0
    on_path = on_path | {group_id}
    return 1 + max(_depth(directory, child, on_path) for child in children)

